    """Reads a single text file and returns a list of words."""
    with open(file_path, 'r', encoding='utf-8') as file:
        return file.read().split()

def read_files(directory):
    """Reads all text files in the given directory and processes them in parallel."""
    futures = []
    with ProcessPoolExecutor() as executor:
        for filename in os.listdir(directory):
            if filename.endswith('.txt'):
                file_path = os.path.join(directory, filename)
                future = executor.submit(read_file, file_path)
                futures.append((filename, future))

        # Collect results
        words = []
        for filename, future in futures:
            try:
                words.extend(future.result())
            except Exception as e:
                print(f"Error reading {filename}: {e}")

    return words

def count_words(words):
    """Counts the frequency of each word in the list of words."""
    return Counter(words)

